    images: ["/products/axa-pdp/X000009645/reef/1.jpg", "/products/axa-pdp/X000009645/reef/2.jpg", "/products/axa-pdp/X000009645/reef/3.jpg", "/products/axa-pdp/X000009645/reef/4.jpg", "/products/axa-pdp/X000009645/reef/5.jpg", "/products/axa-pdp/X000009645/reef/6.jpg", "/products/axa-pdp/X000009645/reef/7.jpg", "/products/axa-pdp/X000009645/reef/8.jpg", "/products/axa-pdp/X000009645/sea-salt/1.jpg", "/products/axa-pdp/X000009645/sea-salt/2.jpg", "/products/axa-pdp/X000009645/sea-salt/3.jpg", "/products/axa-pdp/X000009645/sea-salt/4.jpg", "/products/axa-pdp/X000009645/sea-salt/5.jpg", "/products/axa-pdp/X000009645/sea-salt/6.jpg", "/products/axa-pdp/X000009645/sea-salt/7.jpg", "/products/axa-pdp/X000009645/sea-salt/8.jpg", "/products/axa-pdp/X000009645/black/1.jpg", "/products/axa-pdp/X000009645/black/2.jpg", "/products/axa-pdp/X000009645/black/3.jpg", "/products/axa-pdp/X000009645/black/4.jpg", "/products/axa-pdp/X000009645/black/5.jpg", "/products/axa-pdp/X000009645/black/6.jpg", "/products/axa-pdp/X000009645/black/7.jpg", "/products/axa-pdp/X000009645/black/8.jpg"],
