    images: ["/products/axa-pdp/X000006470/black/1.jpg", "/products/axa-pdp/X000006470/black/2.jpg", "/products/axa-pdp/X000006470/black/3.jpg", "/products/axa-pdp/X000006470/black/4.jpg", "/products/axa-pdp/X000006470/black/5.jpg", "/products/axa-pdp/X000006470/black/6.jpg", "/products/axa-pdp/X000006470/black/7.jpg", "/products/axa-pdp/X000006470/black/8.jpg", "/products/axa-pdp/X000006470/celestia/1.jpg", "/products/axa-pdp/X000006470/celestia/2.jpg", "/products/axa-pdp/X000006470/celestia/3.jpg", "/products/axa-pdp/X000006470/celestia/4.jpg", "/products/axa-pdp/X000006470/celestia/5.jpg", "/products/axa-pdp/X000006470/celestia/6.jpg", "/products/axa-pdp/X000006470/celestia/7.jpg", "/products/axa-pdp/X000006470/celestia/8.jpg"],
