    images: ["/products/axa-pdp/X000009788/blurple/1.jpg", "/products/axa-pdp/X000009788/blurple/2.jpg", "/products/axa-pdp/X000009788/blurple/3.jpg", "/products/axa-pdp/X000009788/blurple/4.jpg", "/products/axa-pdp/X000009788/blurple/5.jpg", "/products/axa-pdp/X000009788/blurple/6.jpg", "/products/axa-pdp/X000009788/blurple/7.jpg", "/products/axa-pdp/X000009788/blurple/8.jpg", "/products/axa-pdp/X000009788/black/1.jpg", "/products/axa-pdp/X000009788/black/2.jpg", "/products/axa-pdp/X000009788/black/3.jpg", "/products/axa-pdp/X000009788/black/4.jpg", "/products/axa-pdp/X000009788/black/5.jpg", "/products/axa-pdp/X000009788/black/6.jpg", "/products/axa-pdp/X000009788/black/7.jpg", "/products/axa-pdp/X000009788/black/8.jpg", "/products/axa-pdp/X000009788/sea-salt/1.jpg", "/products/axa-pdp/X000009788/sea-salt/2.jpg", "/products/axa-pdp/X000009788/sea-salt/3.jpg", "/products/axa-pdp/X000009788/sea-salt/4.jpg", "/products/axa-pdp/X000009788/sea-salt/5.jpg", "/products/axa-pdp/X000009788/sea-salt/6.jpg", "/products/axa-pdp/X000009788/sea-salt/7.jpg", "/products/axa-pdp/X000009788/sea-salt/8.jpg"],
